  },
  {
    "kind": "dialogue",
    "speaker_id": "b9c92e8b-dcba-4dfe-9db0-db8af069ac8a",
    "text": "\"The mill road is clear.\" Wren reports, her voice steady and reassuring.",
    "cited_fact_keys": ["reaction:9fc8efec-427e-5d30-8ab2-d64c5ae784fe"]
  }
]

[
  {
    "kind": "narration",
    "text": "Ash tries to engage Wren in conversation about their dawn patrol plans, but Wren remains silent, waiting for Ash to speak.",
    "cited_fact_keys": ["attempt:communicate", "attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "ae67350f-35cb-4eea-b1f7-ba7ec103095a",
    "text": "Wren finally breaks the silence, saying, 'Tell Ash about the lamps.'",
    "cited_fact_keys": ["reaction:29db82ba-342d-525e-9d64-5a14663378e9"]
  }
]

[
