  },
  {
    "kind": "dialogue",
    "speaker_id": "c5d5cc97-bed3-4745-8ac4-a00f613620f4",
    "text": "'Past the bridge, second left.' Ash responds to Wren.",
    "cited_fact_keys": ["reaction:8520c36d-e398-5f40-87fe-6cd8491e2d33"]
  }
]

[
  {
    "kind": "narration",
    "text": "Ash stood patiently, waiting.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "action",
    "text": "Meanwhile, Wren tried to convey something to Ash.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "dialogue",
    "text": "\"Grain and oilskins.\" Ash said to Wren.",
    "cited_fact_keys": ["reaction:a2f4a15c-4079-548d-a237-6c2e1db1e75f"],
    "speaker_id": "55cd77b3-d251-4c7f-9ac4-2109aa2a232c"
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking, 'Who keeps the lighthouse at night?'",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "action",
    "text": "Ash waits for Wren's question.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "\"Old Marlow, if the lamp is still lit.\"",
    "cited_fact_keys": ["reaction:e41291e5-ac69-4bc5-97b3-64a83fda1feb"],
    "speaker_id": "e41291e5-ac69-4bc5-97b3-64a83fda1feb"
