    "cited_fact_keys": ["reaction:1a9de298-959e-556e-aa27-e12fee6bc996"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren tries to engage Ash in conversation about their dawn patrol, but Ash seems preoccupied.",
    "cited_fact_keys": ["attempt:communicate", "attempt:wait"],
    "speaker_id": null
  },
  {
    "kind": "action",
    "text": "Ash continues to wait, seemingly lost in thought.",
    "cited_fact_keys": ["attempt:wait"],
    "speaker_id": null
  }
]

[
  {
    "kind": "narration",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": null,
    "text": "Wren attempts to communicate with Ash about the dawn patrol."
  },
  {
    "kind": "narration",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": null,
    "text": "Marlow attempts to communicate with Ash, sharing a message about the road's condition."
  },
  {
    "kind": "narration",
    "cited_fact_keys": ["attempt:wait"],
    "speaker_id": null,
    "text": "Ash patiently waits."
  },
  {
    "kind": "dialogue",
    "cited_fact_keys": ["reaction:227e9d2f-4dec-57cd-885a-b056cbadcf3c"],
    "speaker_id": "65e37b74-d528-49fa-b1b7-bf5bfc77744f",
    "text": "\"Dawn bell means the first stalls are opening.\" Ash informs Wren."
  },
  {
    "kind": "dialogue",
    "cited_fact_keys": ["reaction:75d92072-c90d-50b7-acf7-74885289832d"],
    "speaker_id": "63d8b2de-a4aa-4c77-a0b3-3301804f8ec8",
    "text": "\"Aye, and mind the loose stones past the bridge.\" Marlow warns Wren."
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash about the dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": null
  },
  {
    "kind": "narration",
    "text": "Meanwhile, Marlow observes the scene, while Ash patiently waits.",
    "cited_fact_keys": ["attempt:observe", "attempt:wait"],
    "speaker_id": null
  },
  {
    "kind": "dialogue",
    "text": "\"Dawn bell means the market's waking.\" Ash explains to Wren.",
    "cited_fact_keys": ["reaction:4e3981e1-d0e0-50ba-aa04-cc9c18fc435b"],
    "speaker_id": "33e37458-383a-468a-9eff-5d9612657689"
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, trying to discuss their plans for the journey ahead.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Ash, meanwhile, waits patiently for Wren to finish.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "Ash turns to Wren, \"Dawn bell means the market is waking early today, so hurry down with coin and basket before the best bread and freshest fish are gone from the stalls.\"",
    "cited_fact_keys": ["reaction:545ec852-ca9c-5e4d-a178-130d8f0520fc"],
    "speaker_id": "cfe877aa-1969-41f4-845d-3443712ef831"
  }
]

[
  {
    "kind": "narration",
    "text": "Ash waits patiently, his gaze fixed on the old bridge.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "action",
    "text": "Wren tries to engage Ash in conversation, seeking his opinion.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "43e13ab2-64c5-4dcc-8f87-5f6071fd5933",
    "text": "\"No.\" Ash responds curtly to Wren's question about the bridge's safety.",
    "cited_fact_keys": ["reaction:1c9a75e5-11b3-5758-8df1-42cc7eb28a94"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking about the mill.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "action",
    "text": "Ash waits for Wren's response.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "\"It's still standing, unless someone's moved it.\"",
    "speaker_id": "cd8ee8a3-3245-4a88-a438-7d4600f3feeb",
    "cited_fact_keys": ["reaction:2d7e6109-bbdc-582a-9967-81982647cb11"]
  }
]
